from dataclasses import dataclass, field

@dataclass(frozen=True)
class Key:
    org: int
    sku: str

@dataclass
class Job:
    key: Key
    errors: list = field(default_factory=list)

a, b = Job(Key(1, "X")), Job(Key(1, "X"))
a.errors.append("bad row")
print(a.key == b.key, a == b)
